sys_script_include.script:
var SGCeburuIntegrationUtil = Class.create();
SGCeburuIntegrationUtil.prototype = {
    initialize: function() {},

    createRESTMessage: function(endpoint, method, headers, body, queryParams) {
        var RESTMessage = new sn_ws.RESTMessageV2();
        RESTMessage.setEndpoint(endpoint);
        RESTMessage.setHttpMethod(method);
        if (headers) {
            for (var headerName in headers) {
                var headerValue = headers[headerName];
                RESTMessage.setRequestHeader(headerName, headerValue);
            }
        }

        if (body) {
            if (typeof(body) == "string") {
                RESTMessage.setRequestBody(body);
            }else{
                RESTMessage.setRequestBody(JSON.stringify(body));
			}
        }

        if (queryParams) {
            for (var queryParamName in queryParams) {
                var queryValue = queryParams[queryParamName];
                RESTMessage.setQueryParameter(queryParamName, queryValue);
            }
        }

        // RESTMessage.setLogLevel("all");

        var result = RESTMessage.execute();
        return result;
    },

    type: 'SGCeburuIntegrationUtil'
};
